// Normalize usage from different provider response shapes
// Input: provider, model, and provider-specific response object

const provider = $json.provider || $getEnv('DEFAULT_LLM_PROVIDER');
const model = $json.model || $getEnv('DEFAULT_LLM_MODEL');
const response = $json.response || $json;
const workflowId = $json.workflow_id || $getEnv('N8N_WORKFLOW_ID');
const workflowName = $json.workflow_name || $getEnv('N8N_WORKFLOW_NAME');
const executionId = $json.execution_id || $getEnv('N8N_EXECUTION_ID');
const nodeName = $json.node_name || 'LLM Node';
const correlationId = $json.correlation_id || $json.metadata?.correlation_id;
const latencyMs = $json.latency_ms;
const status = $json.status || 'success';

let inputTokens = 0;
let outputTokens = 0;
let cachedTokens = 0;
let estimated = false;

// OpenAI-style usage
if (response.usage) {
  inputTokens = response.usage.prompt_tokens || 0;
  outputTokens = response.usage.completion_tokens || 0;
  cachedTokens = response.usage.prompt_tokens_details?.cached_tokens || 0;
}
// Anthropic-style usage
else if (response.usage && response.usage.input_tokens !== undefined) {
  inputTokens = response.usage.input_tokens || 0;
  outputTokens = response.usage.output_tokens || 0;
  cachedTokens = response.usage.cache_read_input_tokens || 0;
}
// Gemini-style usage
else if (response.usageMetadata) {
  inputTokens = response.usageMetadata.promptTokenCount || 0;
  outputTokens = response.usageMetadata.candidatesTokenCount || 0;
  cachedTokens = response.usageMetadata.cachedContentTokenCount || 0;
}
// Fallback: estimate from text length (very rough: ~4 chars per token)
else if (response.text || response.content || response.output) {
  estimated = true;
  const text = response.text || response.content || response.output || '';
  outputTokens = Math.ceil(text.length / 4);
  // Can't estimate input without the prompt
}

return [{
  json: {
    workflow_id: workflowId,
    workflow_name: workflowName,
    execution_id: executionId,
    node_name: nodeName,
    provider: provider,
    model: model,
    input_tokens: inputTokens,
    output_tokens: outputTokens,
    cached_tokens: cachedTokens,
    latency_ms: latencyMs,
    status: status,
    correlation_id: correlationId,
    metadata: {
      estimated: estimated,
      original_response_keys: Object.keys(response).slice(0, 10)
    }
  }
}];
